[2611]={id=2611,name="G. Zha's Necklace",log_name="Gotoh Zha's necklace",log_plural="Gotoh Zha's necklaces",article=0,description="Neckware of the Mamool Ja, Gotoh Zha\nthe Redolent. Forever imbued with the\nindelible scent of its owner, it can be\nequipped by none other.",category="general",type=1,flags=61524,flag_names={"mystery_box","mail2account","noauction","nosale","nodelivery","ex","rare"},stack=1,targets=0,resource_id=65000,server_name="gotoh_zhas_necklace",sort_name="g._zhas_necklace",server_type=1,ah=0,ah_name="none",base_sell=0},
