[3988]={id=3988,name="Garden Worm",log_name="garden worm",log_plural="garden worms",article=0,description="A long and lithe slimy slitherer that enriches the soil wherever it tunnels.\nIncreases the yield of crops from a furrow.",category="general",type=1,flags=4,flag_names={"mystery_box"},stack=12,targets=0,resource_id=65000,server_name="garden_worm",sort_name="garden_worm",server_type=1,ah=46,ah_name="misc",base_sell=63},
[3989]={id=3989,name="Grove Humus",log_name="clump of grove humus",log_plural="clumps of grove humus",article=0,description="This humus apparently has no official origin, as scholars have yet to ascertain its native habitat.\nReduces the length of a furrow's grow season.",category="general",type=1,flags=4,flag_names={"mystery_box"},stack=12,targets=0,resource_id=65000,server_name="clump_of_grove_humus",sort_name="grove_humus",server_type=1,ah=46,ah_name="misc",base_sell=79},
